#include "particle_attrib.h"

void simulateParticles(ParticleAttrib& attrib) {
    // Update positions based on velocities and accelerations
    for (int i = 0; i < attrib.position.size(); ++i) {
        auto pos = attrib.getPosition(i);
        auto vel = attrib.getVelocity(i);
        auto acc = attrib.getAcceleration(i);

        pos[0] += vel[0] * timestep + 0.5 * acc[0] * timestep * timestep;
        pos[1] += vel[1] * timestep + 0.5 * acc[1] * timestep * timestep;
        pos[2] += vel[2] * timestep + 0.5 * acc[2] * timestep * timestep;

        attrib.setPosition(i, pos);
    }
}
