```cpp
#ifndef IPPL_SRC_MPI_COMMUNICATOR_H_
#define IPPL_SRC_MPI_COMMUNICATOR_H_

#include <mpi.h>

namespace ippl {

class Communicator {
 public:
  Communicator(MPI_Comm comm) : comm_(comm) {}

  // Get the rank of this process within the communicator
  int get_rank() const { return MPI_Comm_rank(comm_, &rank_); }

  // Get the size of the communicator
  int get_size() const { return MPI_Comm_size(comm_, &size_); }

  // Send data to another process
  template <typename T>
  void send(const T& data, int dest, int tag) {
    MPI_Send(&data, sizeof(T), MPI_BYTE, dest, tag, comm_);
  }

  // Receive data from another process
  template <typename T>
  void receive(T& data, int source, int tag) {
    MPI_Recv(&data, sizeof(T), MPI_BYTE, source, tag, comm_, MPI_STATUS_IGNORE);
  }

 private:
  MPI_Comm comm_;
  int rank_;
  int size_;
};

}  // namespace ippl

#endif  // IPPL_SRC_MPI_COMMUNICATOR_H_
```

