```cpp
// File: src/Pixel/ParticleSpatialLayout.cpp

#include "Pixel/ParticleSpatialLayout.hpp"

void ParticleSpatialLayout::rebalanceParticles() {
    // Implementation of particle migration logic using MPI
    int rank, size;
    MPI_Comm_rank(MPI_COMM_WORLD, &rank);
    MPI_Comm_size(MPI_COMM_WORLD, &size);

    // Example: Gather all particles at rank 0 and then scatter them back to other ranks
    if (rank == 0) {
        // Gather particles from all ranks
        std::vector<Particle> allParticles;
        for (int i = 0; i < size; ++i) {
            std::vector<Particle> localParticles;
            MPI_Gather(&particles[0], particles.size(), MPI_Particle, &localParticles[0], localParticles.size(), MPI_Particle, 0, MPI_COMM_WORLD);
            allParticles.insert(allParticles.end(), localParticles.begin(), localParticles.end());
        }
        // Process allParticles
    } else {
        // Scatter particles to the appropriate rank
        std::vector<Particle> localParticles;
        MPI_Scatter(&allParticles[0], particles.size() / size, MPI_Particle, &localParticles[0], particles.size() / size, MPI_Particle, 0, MPI_COMM_WORLD);
        particles = localParticles;
    }
}
```

