// This function solves the Poisson equation using FFT.
void PoissonSolver::solve_poisson_equation(const std::vector<double>& source_charge, std::vector<double>& potential) {
    // Transform source charge to frequency domain using FFT
    std::vector<std::complex<double>> freq_space_source = fft(source_charge);

    // Apply the Poisson kernel in frequency domain
    for (size_t i = 0; i < freq_space_source.size(); ++i) {
        double k_squared = calculate_k_squared(i, source_charge.size());
        if (k_squared != 0) {
            freq_space_source[i] /= (-k_squared);
        } else {
            // Avoid division by zero for the origin
            freq_space_source[i] = 0;
        }
    }

    // Transform back to real space using inverse FFT
    potential = ifft(freq_space_source);
}
